"use client";
import { useEffect, useMemo, useState } from "react";

type Product={id:string;name:string;category:string|null;sellingPrice:number|string;stockQuantity:number};
type CartItem={product:Product;quantity:number};
const money=(v:number|string)=>`₦${Number(v).toLocaleString()}`;

export default function SalesPage(){
 const [products,setProducts]=useState<Product[]>([]); const [cart,setCart]=useState<CartItem[]>([]); const [method,setMethod]=useState("CASH"); const [q,setQ]=useState(""); const [loading,setLoading]=useState(true); const [submitting,setSubmitting]=useState(false); const [message,setMessage]=useState("");
 async function load(){setLoading(true);try{const r=await fetch(`/api/products${q?`?search=${encodeURIComponent(q)}`:""}`);const d=await r.json();if(!r.ok)throw new Error(d.error||"Unable to load products");setProducts(d.products)}catch(e){setMessage(e instanceof Error?e.message:"Unable to load products")}finally{setLoading(false)}}
 useEffect(()=>{const t=setTimeout(load,250);return()=>clearTimeout(t)},[q]);
 function add(p:Product){setCart(c=>{const found=c.find(x=>x.product.id===p.id);if(found)return c.map(x=>x.product.id===p.id?{...x,quantity:Math.min(x.quantity+1,p.stockQuantity)}:x);return [...c,{product:p,quantity:1}]})}
 function change(id:string,delta:number){setCart(c=>c.flatMap(x=>x.product.id===id?((x.quantity+delta<=0)?[]:[{...x,quantity:Math.min(x.quantity+delta,x.product.stockQuantity)}]):[x]))}
 const total=useMemo(()=>cart.reduce((s,x)=>s+Number(x.product.sellingPrice)*x.quantity,0),[cart]);
 async function complete(){if(!cart.length)return;setSubmitting(true);setMessage("");try{const r=await fetch("/api/sales",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({payment:method,items:cart.map(x=>({productId:x.product.id,quantity:x.quantity}))})});const d=await r.json();if(!r.ok)throw new Error(d.error||"Unable to complete sale");setMessage(`Sale completed. Receipt: ${d.sale.receiptNo}`);setCart([]);load()}catch(e){setMessage(e instanceof Error?e.message:"Unable to complete sale")}finally{setSubmitting(false)}}
 return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-7xl"><div className="mb-7 flex items-center justify-between"><div><p className="text-xl font-bold">TX <span className="text-orange-500">RetailOS</span></p><h1 className="mt-4 text-2xl font-semibold">Sales</h1></div><a href="/employee-dashboard" className="text-sm text-white/50 hover:text-white">Dashboard</a></div>{message&&<div className="mb-4 rounded-xl border border-white/10 bg-[#151515] p-3 text-sm text-orange-300">{message}</div>}<div className="grid gap-6 lg:grid-cols-[1fr_360px]"><section className="rounded-2xl border border-white/10 bg-[#151515] p-5"><div className="mb-5 flex items-center justify-between gap-3"><h2 className="font-semibold">Products</h2><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search products..." className="field max-w-sm"/></div>{loading?<p className="py-12 text-center text-white/40">Loading products...</p>:<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{products.map(p=><article key={p.id} className="rounded-xl border border-white/10 bg-[#101010] p-4"><div className="mb-6 h-20 rounded-lg bg-white/5"/><h3 className="font-medium">{p.name}</h3><p className="mt-1 text-orange-400">{money(p.sellingPrice)}</p><p className="mt-1 text-xs text-white/40">{p.stockQuantity} in stock</p><button disabled={!p.stockQuantity} onClick={()=>add(p)} className="mt-4 w-full rounded-lg bg-orange-500 px-3 py-2 text-sm font-semibold text-black disabled:bg-white/10 disabled:text-white/30">{p.stockQuantity?"Add to cart":"Out of stock"}</button></article>)}</div>}</section><aside className="h-fit rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="mb-5 font-semibold">Cart</h2><div className="min-h-32 space-y-2">{cart.length?cart.map(x=><div key={x.product.id} className="flex items-center justify-between rounded-lg bg-white/5 px-3 py-2 text-sm"><div><p>{x.product.name}</p><p className="text-xs text-white/40">{money(x.product.sellingPrice)} × {x.quantity}</p></div><div className="flex items-center gap-2"><button onClick={()=>change(x.product.id,-1)} className="rounded bg-white/10 px-2">−</button><button onClick={()=>change(x.product.id,1)} className="rounded bg-white/10 px-2">+</button></div></div>):<p className="py-8 text-center text-sm text-white/30">Cart is empty</p>}</div><div className="my-5 flex justify-between border-t border-white/10 pt-4"><span>Total</span><strong>{money(total)}</strong></div><p className="mb-2 text-xs text-white/40">Payment Method</p><div className="grid grid-cols-3 gap-2">{["CASH","TRANSFER","POS"].map(x=><button key={x} onClick={()=>setMethod(x)} className={`rounded-lg px-2 py-2 text-xs ${method===x?"bg-orange-500 text-black":"bg-white/5 text-white/60"}`}>{x}</button>)}</div><button disabled={!cart.length||submitting} onClick={complete} className="mt-4 w-full rounded-xl bg-orange-500 py-3 font-semibold text-black disabled:bg-white/10 disabled:text-white/30">{submitting?"Processing...":"Complete Sale"}</button></aside></div></div></main>}
